from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            comps.append((color, cells))

    # For each elbow in a non-background component, continue both arms away
    # from the elbow. The first component on either ray is recolored.
    changes = []
    for color, cells in comps:
        for r, c in cells:
            for vr in (-1, 1):
                for hc in (-1, 1):
                    if (r+vr, c) not in cells or (r, c+hc) not in cells:
                        continue
                    # Each arm must continue at least one more cell or be a
                    # clear one-cell arm at a corner-like L elbow.
                    for y, x, dy, dx in ((r-vr, c, -vr, 0), (r, c-hc, 0, -hc)):
                        while 0 <= y < h and 0 <= x < w:
                            val = grid[y][x]
                            if val != bg and val != color:
                                target = next((part for other, part in comps
                                               if other == val and (y, x) in part), None)
                                if target:
                                    changes.append((color, target))
                                break
                            y += dy
                            x += dx
    for color, cells in changes:
        for r, c in cells:
            out[r][c] = color
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))", "exit_code": 0, "error": null}

